import 'package:flutter/material.dart';
import '../../data/models/models.dart';
import '../../data/sample/sample_data.dart';
import 'exercise_screen.dart';
class LessonScreen extends StatelessWidget { final Chapter chapter; const LessonScreen({super.key,required this.chapter}); @override Widget build(BuildContext context){final lessons=demoLessons.where((l)=>l.chapterId==chapter.id).toList();return Scaffold(appBar:AppBar(title:Text(chapter.title)),body:ListView(padding:const EdgeInsets.all(16),children:[if(lessons.isEmpty)const Text('Les leçons de ce chapitre seront bientôt disponibles.'),...lessons.map((l)=>Card(child:ListTile(leading:const Icon(Icons.article_outlined),title:Text(l.title),subtitle:Text(l.summary),trailing:const Icon(Icons.chevron_right),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>LessonContentScreen(lesson:l))))))]));}}
class LessonContentScreen extends StatelessWidget { final Lesson lesson; const LessonContentScreen({super.key,required this.lesson}); @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(lesson.title)),body:ListView(padding:const EdgeInsets.all(20),children:[Text(lesson.summary,style:const TextStyle(fontSize:19,fontWeight:FontWeight.bold)),const SizedBox(height:16),Text(lesson.content,style:const TextStyle(fontSize:16,height:1.6)),const SizedBox(height:20),const Text('À retenir',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),...lesson.keyPoints.map((p)=>ListTile(leading:const Icon(Icons.check_circle,color:Color(0xFF006A4E)),title:Text(p))),const SizedBox(height:20),FilledButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>ExerciseScreen(lesson:lesson))),child:const Text('Faire les exercices'))]));}
